  ]);

  const DISPLAY_TOKENS = new Set([
    'block',
    'inline-block',
    'inline',
    'flex',
    'inline-flex',
    'grid',
    'inline-grid',
    'hidden',
  ]);

  function parseInputs(args: unknown[]): string[] {
    const tokens: string[] = [];
