    btn3?.hasAttribute('disabled') &&
    cls3.includes('disabled:opacity-50') &&
    cls3.includes('disabled:pointer-events-none');
  $test.check(case3, Boolean(pass3), { hasDisabled: btn3?.hasAttribute('disabled'), classList: cls3 });
  u3();

  // Case 4: Extra props forwarding
  let clicked = false;
  const { container: c4, unmount: u4 } = render(
    React.createElement(
      Component,
      {
        'data-testid': 'custom-btn',
        'aria-label': 'Custom Action',
        onClick: () => { clicked = true; },
      },
      'Click Me'
    )
  );
  const btn4 = c4.querySelector('button[data-testid="custom-btn"]');
  btn4?.click();
  const pass4 = Boolean(btn4) &&
    btn4?.getAttribute('aria-label') === 'Custom Action' &&
    clicked === true;
  $test.check(case4, Boolean(pass4), { found: Boolean(btn4), clicked });
  u4();
})();

tailwind-button-basics.referenceSolution:
function Button({
  variant = 'primary',
  disabled = false,
  children,
  type = 'button',
  ...props
}) {
  const baseClasses =
    'inline-flex items-center justify-center font-medium rounded-lg px-4 py-2 text-sm transition-colors focus-visible:outline-none focus-visible:ring-2 active:scale-95 cursor-pointer';

  const variantClasses =
    variant === 'outline'
      ? 'border border-gray-300 text-gray-700 hover:bg-gray-50 focus-visible:ring-gray-400'
      : 'bg-blue-600 text-white hover:bg-blue-700 focus-visible:ring-blue-500';

  const disabledClasses = disabled
    ? 'disabled:opacity-50 disabled:pointer-events-none cursor-not-allowed'
    : '';

  const className = [baseClasses, variantClasses, disabledClasses, props.className]
    .filter(Boolean)
    .join(' ');

  return React.createElement(
    'button',
    {
      type,
      disabled,
      className,
      ...props,
    },
    children
  );
}

